export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (issue #1) --------------------------------

// Liang–Barsky segment/rectangle intersection. True when the segment from
// (x0,y0) to (x1,y1) crosses the rectangle. Used to close the tunnelling gap:
// at high level speed a single frame can carry the ball straight across a
// brick without the ball ever *being inside* it, so an overlap-only test would
// miss the hit entirely.
function segmentHitsRect(x0, y0, x1, y1, rx0, ry0, rx1, ry1) {
  let t0 = 0;
  let t1 = 1;
  const p = [x0 - x1, x1 - x0, y0 - y1, y1 - y0];
  const q = [x0 - rx0, rx1 - x0, y0 - ry0, ry1 - y0];

  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return false;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return false;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return false;
        if (t < t1) t1 = t;
      }
    }
  }
  return t0 <= t1;
}

// True if the ball's path during the last step crossed this brick even though
// the ball no longer overlaps it (the tunnelling bridge).
function bridged(ball, brick, prev) {
  const e = ball.r;
  return segmentHitsRect(
    prev.x, prev.y,
    ball.x, ball.y,
    brick.x - e, brick.y - e,
    brick.x + brick.w + e, brick.y + brick.h + e,
  );
}

// Flips the ball velocity on the proper face and pushes it back out of the
// brick so it never re-collides on the following frame (sticky bounce).
//
// * penetration decides the face: the axis with the *smaller* overlap was hit,
//   equal overlap means a diagonal corner hit — flip both axes;
// * a swept (tunnelled) hit has no meaningful overlap, so the entry face is
//   instead derived from the approach direction;
// * the ball is then placed just outside the brick it is now heading away from.
function resolveBounce(ball, brick, prev, swept) {
  if (swept) {
    const cameFromRight = prev.x >= brick.x + brick.w;
    const cameFromLeft = prev.x <= brick.x;
    if (cameFromRight || cameFromLeft) {
      // Side hit: horizontal bounce, out the face it came in through.
      ball.vx = cameFromRight ? -Math.abs(ball.vx) : Math.abs(ball.vx);
      ball.x = cameFromRight ? brick.x + brick.w + ball.r : brick.x - ball.r;
    } else {
      // Top/bottom hit: vertical bounce.
      const cameFromBottom = prev.y >= brick.y + brick.h;
      ball.vy = cameFromBottom ? -Math.abs(ball.vy) : Math.abs(ball.vy);
      ball.y = cameFromBottom ? brick.y + brick.h + ball.r : brick.y - ball.r;
    }
    return;
  }

  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  if (overlapX < overlapY) {
    // Side hit: flip horizontal, push out to the left or right face.
    ball.vx = -ball.vx;
    ball.x = ball.vx > 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: flip vertical, push out to the top or bottom face.
    ball.vy = -ball.vy;
    ball.y = ball.vy > 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner: flip both axes and push out along both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.vx > 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.vy > 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

// Pure, testable brick-collision step. Marks the first live brick the ball
// touched as hit, deflects the ball off it, and returns that brick (or null).
//
// Exactly ONE brick is resolved per call: the grid gap (8px) is smaller than
// the ball (14px), so a seam overlaps two bricks in the same pass — flipping
// the velocity on both would apply twice and cancel out, letting the ball
// through. Resolving a single brick keeps that from happening (the pushed-out
// ball then moves away toward the neighbour's other side on later frames).
export function brickHit(state) {
  const { ball, bricks } = state;
  const prev = ball.prev ?? ball;
  const hasPrev = ball.prev != null;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const overlaps = collides(ball, brick);
    const swept = !overlaps && hasPrev && bridged(ball, brick, prev);
    if (!overlaps && !swept) continue;

    brick.alive = false;
    resolveBounce(ball, brick, prev, swept);
    return brick; // exactly one bounce per frame
  }
  return null;
}

