// Builds a state with the ball inside the first brick and records how it bounces.
function stateWithBallOnFirstBrick(vx) {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h / 2,
    r: 7,
    vx,
    vy: 200,
    prev: { x: brick.x + brick.w / 2, y: brick.y - 30 }, // approaching from the top
  };
  return state;
}

function makeBrick(x, y, w, h) {
  return { x, y, w, h, row: 0, alive: true, points: 10 };
}

test('brickHit: destroys the brick it hits', () => {
  const state = stateWithBallOnFirstBrick(0);
  const hit = brickHit(state);
  assert.equal(hit, state.bricks[0]);
  assert.equal(state.bricks[0].alive, false);
});

test('brickHit: top/bottom hit flips vy, keeps vx, and pushes the ball out', () => {
  const state = stateWithBallOnFirstBrick(0); // ball centred on the brick, vy > 0
  const prevVy = state.ball.vy;
  const prevVx = state.ball.vx;
  brickHit(state);
  // Flips vertical.
  assert.equal(state.ball.vy, -prevVy);
  assert.equal(state.ball.vx, prevVx);
  // Pushed back OUT of the brick (above its top face, since it was moving down).
  assert.ok(state.ball.y > 0);
  assert.ok(
    state.ball.y + state.ball.r <= state.bricks[0].y,
    `ball left at y=${state.ball.y} should sit above the brick's top (${state.bricks[0].y})`,
  );
});

test('brickHit: side hit flips vx, keeps vy', () => {
  const brick = makeBrick(200, 100, 40, 20);
  const state = {
    bricks: [brick],
    ball: {
      x: brick.x - 1, // just inside the left face
      y: brick.y + brick.h / 2,
      r: 7,
      vx: +300,
      vy: 0,
      prev: { x: brick.x - 30, y: brick.y + brick.h / 2 }, // approaching from the left
    },
  };
  brickHit(state);
  assert.equal(state.ball.vx, -300, 'vx should flip on a side hit');
  assert.equal(state.ball.vy, 0, 'vy should be untouched on a side hit');
  assert.ok(
    state.ball.x + state.ball.r <= brick.x,
    'ball should be pushed left, out of the brick',
  );
});

test('brickHit: corner hit flips both axes', () => {
  const brick = makeBrick(200, 100, 40, 20);
  const state = {
    bricks: [brick],
    ball: {
      x: brick.x + 1, // inside, near the top-left corner
      y: brick.y + 1,
      r: 7,
      vx: -300,
      vy: +200,
      prev: { x: brick.x - 20, y: brick.y - 20 }, // diagonal approach
    },
  };
  const { vx, vy } = state.ball;
  brickHit(state);
  assert.equal(state.ball.vx, -vx);
  assert.equal(state.ball.vy, -vy);
  assert.ok(!collides(state.ball, brick), 'ball must be pushed out of the brick');
});

