test('brickHit: corner hit flips both axes', () => {
  const brick = makeBrick(200, 100, 40, 20);
  const state = {
    bricks: [brick],
    ball: {
      x: brick.x + 1,
      y: brick.y + 1,
      r: 7,
      vx: -300,
      vy: +200,
      prev: { x: brick.x - 20, y: brick.y - 20 },
    },
  };
  const { vx, vy } = state.ball;
  brickHit(state);
  assert.equal(state.ball.vx, -vx);
  assert.equal(state.ball.vy, -vy);
  assert.ok(!collides(state.ball, brick), 'ball must be pushed out of the brick');
});

test('brickHit: tunnelled hit (high speed) is still caught', () => {
  // The ball lands fully PAST the brick (no overlap) but its last-step path
  // crossed it — the straddling frame a fast/under-capped frame produces at
  // high level speed. The sweep must catch it and bounce it back up.
  const brick = makeBrick(200, 100, 40, 20);
  const state = {
    bricks: [brick],
    ball: {
      x: brick.x + brick.w / 2, // centred over the brick row
      y: brick.y + brick.h + 15, // already below the brick (no overlap)
      r: 7,
      vx: 0,
      vy: +710,
      prev: { x: brick.x + brick.w / 2, y: brick.y - 20 }, // path crossed the brick
    },
  };
  assert.equal(collides(state.ball, brick), false, 'precondition: no overlap after the step');
  const hit = brickHit(state);
  assert.equal(hit, brick, 'the swept path must register a hit');
  assert.equal(state.ball.alive, undefined, 'ball has no alive flag');
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, `vy should flip upward after the sweep, got ${state.ball.vy}`);
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'ball pushed back above the brick');
});

