content.text:
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (issue #1) --------------------------------

// Liang–Barsky segment/rectangle intersection. True when the segment from
// (x0,y0) to (x1,y1) crosses the rectangle. Used to close the tunnelling gap:
// at high level speed a single frame can carry the ball straight across a
// brick without the ball ever *being inside* it, so an overlap-only test would
// miss the hit entirely.
function segmentHitsRect(x0, y0, x1, y1, rx0, ry0, rx1, ry1) {
  let t0 = 0;
  let t1 = 1;
  const p = [x0 - x1, x1 - x0, y0 - y1, y1 - y0];
  const q = [x0 - rx0, rx1 - x0, y0 - ry0, ry1 - y0];

  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return false;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return false;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return false;
        if (t < t1) t1 = t;
      }
    }
  }
  return t0 <= t1;
}

// True if the ball's path during the last step crossed this brick even though
// the ball no longer overlaps it (the tunnelling bridge).
function bridged(ball, brick, prev) {
  const e = ball.r;
  return segmentHitsRect(
    prev.x, prev.y,
    ball.x, ball.y,
    brick.x - e, brick.y - e,
    brick.x + brick.w + e, brick.y + brick.h + e,
  );
}

// Flips the ball velocity on the proper face and pushes it back out of the
// brick so it never re-collides on the following frame (sticky bounce).
//
// * penetration decides the face: the axis with the *smaller* overlap was hit,
//   equal overlap means a diagonal corner hit — flip both axes;
// * the velocity sign (its direction *into* the brick) chooses which side it
//   entered from, so the ball bounces back out the very face it came through.
//   This also makes swept/tunnelled hits (ball already past the brick) resolve
//   correctly, as the incoming sign is preserved.
function resolveBounce(ball, brick) {
  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  // Moving down (+vy) -> the ball hit the brick's TOP face; moving right (+vx)
  // -> it hit the LEFT face. So the return side is the opposite of each sign.
  const fromTop = ball.vy > 0;
  const fromLeft = ball.vx > 0;

  if (overlapX < overlapY) {
    // Side hit: horizontal bounce, back out the face it entered through.
    ball.vx = fromLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: vertical bounce.
    ball.vy = fromTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner: flip both axes and push out along both.
    ball.vx = fromLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = fromTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
